query.nhcp_marker:
SELECT ?item ?c ?en ?tl WHERE {
  ?item wdt:P31 wd:Q21562164; wdt:P625 ?c.
  OPTIONAL { ?item rdfs:label ?en FILTER(LANG(?en) = "en") }
  OPTIONAL { ?item rdfs:label ?tl FILTER(LANG(?tl) = "tl") }
}

